const osCodes=Array.from({length:11},(_,i)=>`OS-${String(i+1).padStart(2,"0")}`);
const labelStatus:Record<string,string>={vacant:"Vacant",partially_filled:"Partiellement pourvu",filled:"Pourvu",suspended:"Suspendu",abolished:"Supprimé structurellement",planned:"Planifié",active:"Actif",ended:"Terminé",draft:"Brouillon",to_orient:"À orienter",transmitted:"Transmis",processing:"En traitement",waiting:"En attente",validated:"Validé",sent:"Envoyé",replied:"Répondu",closed:"Clôturé",no_action:"Sans suite",archived:"Archivé",open:"Ouvert",assessment:"Évaluation",on_hold:"En pause",transferred:"Transféré"};
